import React, { useState, useEffect } from 'react';
import { attendanceService } from '../../services/attendanceService';
import '../../styles/table.scss';

const AttendanceList = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]); // YYYY-MM-DD

  useEffect(() => {
    fetchAttendance();
  }, [date]);

  const fetchAttendance = async () => {
    try {
      setLoading(true);
      const result = await attendanceService.getTodayAttendance(date);
      if (result.success) {
        setData(result.data);
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError('Lỗi khi tải dữ liệu chấm công');
    } finally {
      setLoading(false);
    }
  };

  const getStatusClass = (status) => {
    switch (status) {
      case 'Present': return 'present';
      case 'Absent': return 'absent';
      case 'Leave': return 'leave';
      default: return '';
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'Present': return 'Có mặt';
      case 'Absent': return 'Vắng mặt';
      case 'Leave': return 'Nghỉ phép';
      default: return status;
    }
  };

  return (
    <div className="attendance-list-page animate-fade-in" style={{ padding: '2rem' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
        <h1 style={{ fontSize: '1.875rem', fontWeight: 'bold', color: '#1f2937' }}>Danh sách chấm công</h1>
        <div>
          <label style={{ marginRight: '1rem', fontWeight: '500' }}>Chọn tháng báo cáo: </label>
          <input 
            type="date" 
            value={date}
            onChange={(e) => setDate(e.target.value)}
            style={{ padding: '0.5rem', borderRadius: '8px', border: '1px solid #e5e7eb' }}
          />
        </div>
      </div>

      {error && <div style={{ padding: '1rem', backgroundColor: '#fee2e2', color: '#ef4444', borderRadius: '8px', marginBottom: '1rem' }}>{error}</div>}

      <div className="modern-table-container">
        {loading ? (
          <div style={{ padding: '2rem', textAlign: 'center' }}>Đang tải dữ liệu...</div>
        ) : (
          <table>
            <thead>
              <tr>
                <th>Mã NV</th>
                <th>Họ Tên</th>
                <th>Phòng Ban</th>
                <th>Chức Vụ</th>
                <th>Số giờ làm</th>
                <th>Trạng thái</th>
              </tr>
            </thead>
            <tbody>
              {data.map((row) => (
                <tr key={row.EmployeeID}>
                  <td>{row.EmployeeCode}</td>
                  <td style={{ fontWeight: '500' }}>{row.FullName}</td>
                  <td>{row.DepartmentName}</td>
                  <td>{row.PositionName}</td>
                  <td>{row.WorkHours} giờ</td>
                  <td>
                    <span className={`status-badge ${getStatusClass(row.Status)}`}>
                      {getStatusText(row.Status)}
                    </span>
                  </td>
                </tr>
              ))}
              {data.length === 0 && (
                <tr>
                  <td colSpan="6" style={{ textAlign: 'center', padding: '2rem' }}>Không có dữ liệu</td>
                </tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default AttendanceList;
